-- SAP ECC 6.0 -> canonical SUPPLIER (SAP_B). Generated by tools/build_silver_sql.py.
SELECT 'SAP_B' AS SOURCE_SLOT, 'SAP ECC 6.0' AS SOURCE_SYSTEM, l.LIFNR AS SUPPLIER_ID, l.NAME1 AS SUPPLIER_NAME, l.LAND1 AS COUNTRY, l.STCD1 AS TAX_ID, l.KRAUS AS DUNS, b.ZTERM AS PAYMENT_TERMS
FROM {{ source('src_ecc_b', 'lfa1') }} l LEFT JOIN (SELECT LIFNR, ANY_VALUE(ZTERM) ZTERM FROM {{ source('src_ecc_b', 'lfb1') }} GROUP BY 1) b ON b.LIFNR = l.LIFNR
